sql.where:
A.ATM_STATUS IN ('1', '2')

    AND A.TERM_GROUP_ID = #{termGroupId}


    AND A.BRANCH_CD = #{branchCd}


    AND A.CORNER_CD = #{cornerCd}


    AND A.TERM_ID LIKE '%' || #{termId} || '%'


    AND A.ATM_CO_CD = #{atmCoCd}


    AND A.MODEL_CD = #{modelCd}

mapper.select:
SELECT A.TERM_GROUP_ID, A.TERM_ID
  FROM T_ATM A
 WHERE A.ATM_STATUS IN ('1', '2')
   AND A.ATM_CO_CD = #{atmCoCd}
   AND A.MODEL_CD  = #{modelCd}
 ORDER BY A.TERM_GROUP_ID, A.TERM_ID

sql.where:
P.USE_YN = 'Y'

    AND P.ATM_CO_CD = #{atmCoCd}


    AND P.MODEL_CD = #{modelCd}


    AND P.PKG_TYPE = #{pkgType}


    AND P.CONFIRM_STATUS = #{confirmStatus}
